export function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  return createStore(options.storage, options.masterPassword);
}

const SALT_KEY = "\x00ss-salt\x00";
const SECRET_PREFIX = "secret\x00";
const IV_LENGTH = 12;
const PBKDF2_ITERATIONS = 100_000;

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

function base64ToBytes(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function toBase64(str: string): string {
  return bytesToBase64(new TextEncoder().encode(str));
}

function fromBase64(b64: string): string {
  return new TextDecoder().decode(base64ToBytes(b64));
}

async function deriveKey(password: string, salt: Uint8Array): Promise<CryptoKey> {
  const baseKey = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: PBKDF2_ITERATIONS,
      hash: "SHA-256",
    },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}

async function createStore(
  storage: KeyValueStorage,
  masterPassword: string,
): Promise<SecretStore> {
  // Get or create salt
  let saltB64 = await storage.get(SALT_KEY);
  let salt: Uint8Array;
  if (saltB64 !== undefined) {
    salt = base64ToBytes(saltB64);
  } else {
    salt = crypto.getRandomValues(new Uint8Array(32));
    await storage.set(SALT_KEY, bytesToBase64(salt));
  }

  const key = await deriveKey(masterPassword, salt);

  function secretKey(owner: string, name: string): string {
    return `secret\x00${toBase64(owner)}\x00${toBase64(name)}`;
  }

  function ownerPrefix(owner: string): string {
    return `secret\x00${toBase64(owner)}\x00`;
  }

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
      const aad = new TextEncoder().encode(secretKey(owner, name));
      const plaintext = new TextEncoder().encode(value);
      const ciphertext = await crypto.subtle.encrypt(
        { name: "AES-GCM", iv, additionalData: aad },
        key,
        plaintext,
      );
      const combined = new Uint8Array(IV_LENGTH + ciphertext.byteLength);
      combined.set(iv, 0);
      combined.set(new Uint8Array(ciphertext), IV_LENGTH);
      await storage.set(secretKey(owner, name), bytesToBase64(combined));
    },

    async get(owner: string, name: string): Promise<string | undefined> {
      const stored = await storage.get(secretKey(owner, name));
      if (stored === undefined) return undefined;
      let data: Uint8Array;
      try {
        data = base64ToBytes(stored);
      } catch {
        throw new Error("Stored data is corrupted");
      }
      if (data.length < IV_LENGTH) {
        throw new Error("Stored data is corrupted");
      }
      const iv = data.slice(0, IV_LENGTH);
      const ciphertext = data.slice(IV_LENGTH);
      const aad = new TextEncoder().encode(secretKey(owner, name));
      try {
        const plaintext = await crypto.subtle.decrypt(
          { name: "AES-GCM", iv, additionalData: aad },
          key,
          ciphertext,
        );
        return new TextDecoder().decode(plaintext);
      } catch {
        throw new Error("Failed to decrypt secret (possible tampering)");
      }
    },

    async list(owner: string): Promise<string[]> {
      const prefix = ownerPrefix(owner);
      const allKeys = await storage.keys();
      const names = allKeys
        .filter((k) => k.startsWith(prefix))
        .map((k) => {
          const namePart = k.slice(prefix.length);
          return fromBase64(namePart);
        })
        .sort();
      return names;
    },

    async remove(owner: string, name: string): Promise<boolean> {
      const k = secretKey(owner, name);
      const stored = await storage.get(k);
      if (stored === undefined) return false;
      await storage.delete(k);
      return true;
    },
  };
}
